1	package tariff
2	
3	import (
4		"errors"
5		"fmt"
6		"sync"
7		"testing"
8		"time"
9	)
10	
11	func ptrTime(t time.Time) *time.Time { return &t }
12	
13	// EffectiveVersionAt 场景的固定时间线（UTC，结束时刻均不含）：
14	//
15	//	旧版 seat-v1：单价 150 分，2026-03-01 00:00 起生效，登记结束 2026-03-31 00:00
16	//	新版 seat-v2：单价 180 分，2026-03-10 00:00 起替代旧版，2026-03-20 00:00 结束
17	//
18	// 查询时旧版的实际有效区间已被截断到 3 月 10 日：
19	// 3 月 9 日应选旧版，3 月 10 日应选新版，3 月 20 日两版都不生效且旧版不恢复。
20	var (
21		effV1Start = time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC)
22		effV1End   = time.Date(2026, 3, 31, 0, 0, 0, 0, time.UTC)
23		effV2Start = time.Date(2026, 3, 10, 0, 0, 0, 0, time.UTC)
24		effV2End   = time.Date(2026, 3, 20, 0, 0, 0, 0, time.UTC)
25	)
26	
27	func newEffectiveVersionBook(t *testing.T, start time.Time) (*Book, func(time.Time)) {
28		t.Helper()
29		now, setNow := fixedClock(start)
30		b := NewBook(WithClock(now))
31		v1End := effV1End
32		if err := b.RegisterVersion(RegisterRequest{
33			ItemID: "seat", VersionID: "seat-v1", UnitPrice: 150,
34			Start: effV1Start, End: &v1End,
35		}); err != nil {
36			t.Fatalf("register seat-v1: %v", err)
37		}
38		v2End := effV2End
39		if err := b.RegisterVersion(RegisterRequest{
40			ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180,
41			Start: effV2Start, End: &v2End, Replaces: "seat-v1",
42		}); err != nil {
43			t.Fatalf("register seat-v2: %v", err)
44		}
45		return b, setNow
46	}
47	
48	// 题目示例：3 月 9 日返回旧版，3 月 10 日返回新版，
49	// 3 月 20 日明确表示当时没有生效版本，不能恢复旧版。
50	func TestEffectiveVersionAtHandoffExample(t *testing.T) {
51		b, _ := newEffectiveVersionBook(t, effV1Start)
52	
53		got, err := b.EffectiveVersionAt("seat", time.Date(2026, 3, 9, 0, 0, 0, 0, time.UTC))
54		if err != nil {
55			t.Fatalf("3 月 9 日旧版应生效: %v", err)
56		}
57		if got.VersionID != "seat-v1" || got.UnitPrice != 150 {
58			t.Fatalf("3 月 9 日选错版本: %+v", got)
59		}
60	
61		got, err = b.EffectiveVersionAt("seat", effV2Start)
62		if err != nil {
63			t.Fatalf("3 月 10 日新版应生效: %v", err)
64		}
65		if got.VersionID != "seat-v2" || got.UnitPrice != 180 {
66			t.Fatalf("3 月 10 日选错版本: %+v", got)
67		}
68	
69		_, err = b.EffectiveVersionAt("seat", effV2End)
70		if !errors.Is(err, ErrNoEffectiveVersion) {
71			t.Fatalf("3 月 20 日应无生效版本, got %v (view=%+v)", err, got)
72		}
73	}
74	
75	// 边界与“旧版不恢复”：开始时刻含、结束时刻不含；
76	// 旧版登记结束（3 月 31 日）即使仍在将来，交接点之后也不能再被选中；
77	// 新版到期后同样不能回退到旧版；更远的未来仍然没有生效版本。
78	func TestEffectiveVersionAtBoundariesAndNoRevival(t *testing.T) {
79		b, _ := newEffectiveVersionBook(t, effV1Start)
80	
81		cases := []struct {
82			name    string
83			at      time.Time
84			wantID  string
85			wantErr error
86		}{
87			{"首版开始时刻（含）", effV1Start, "seat-v1", nil},
88			{"交接点前1纳秒仍是旧版", effV2Start.Add(-time.Nanosecond), "seat-v1", nil},
89			{"交接点本身起选新版", effV2Start, "seat-v2", nil},
90			{"新版结束前1纳秒仍是新版", effV2End.Add(-time.Nanosecond), "seat-v2", nil},
91			{"新版结束时刻（不含）无生效版本", effV2End, "", ErrNoEffectiveVersion},
92			// 3 月 25 日：旧版登记结束 3 月 31 日尚未到，但旧版实际区间止于 3 月 10 日。
93			{"两版都失效后不回退旧版", time.Date(2026, 3, 25, 0, 0, 0, 0, time.UTC), "", ErrNoEffectiveVersion},
94			{"旧版登记结束当天仍无生效版本", effV1End, "", ErrNoEffectiveVersion},
95			{"更远的未来仍无生效版本", time.Date(2027, 1, 1, 0, 0, 0, 0, time.UTC), "", ErrNoEffectiveVersion},
96		}
97		for _, c := range cases {
98			got, err := b.EffectiveVersionAt("seat", c.at)
99			if c.wantErr != nil {
100				if !errors.Is(err, c.wantErr) {
101					t.Fatalf("%s: want %v, got %v", c.name, c.wantErr, err)
102				}
103				continue
104			}
105			if err != nil {
106				t.Fatalf("%s: 不应返回错误, got %v", c.name, err)
107			}
108			if got.VersionID != c.wantID {
109				t.Fatalf("%s: 选中 %q, want %q", c.name, got.VersionID, c.wantID)
110			}
111		}
112	}
113	
114	// 早于首版开始、落在两版之间的空档、晚于最后一版结束，
115	// 都返回可识别的“该时刻无生效版本”，不拿邻近版本补位。
116	func TestEffectiveVersionAtBeforeFirstAndGaps(t *testing.T) {
117		b := NewBook()
118		must := func(r RegisterRequest) {
119			t.Helper()
120			if err := b.RegisterVersion(r); err != nil {
121				t.Fatalf("register %+v: %v", r, err)
122			}
123		}
124		// 不涉及替代的两段区间，中间留 3 月 10 日至 3 月 20 日的空档。
125		g1End := time.Date(2026, 3, 10, 0, 0, 0, 0, time.UTC)
126		must(RegisterRequest{
127			ItemID: "gap", VersionID: "g1", UnitPrice: 100,
128			Start: time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC), End: &g1End,
129		})
130		must(RegisterRequest{
131			ItemID: "gap", VersionID: "g2", UnitPrice: 200,
132			Start: time.Date(2026, 3, 20, 0, 0, 0, 0, time.UTC),
133			End:   ptrTime(time.Date(2026, 3, 30, 0, 0, 0, 0, time.UTC)),
134		})
135	
136		none := []struct {
137			name string
138			at   time.Time
139		}{
140			{"早于首版开始", time.Date(2026, 2, 28, 0, 0, 0, 0, time.UTC)},
141			{"首版开始前1纳秒", time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC).Add(-time.Nanosecond)},
142			{"第一段结束时刻（不含）", time.Date(2026, 3, 10, 0, 0, 0, 0, time.UTC)},
143			{"两版之间的空档", time.Date(2026, 3, 15, 12, 0, 0, 0, time.UTC)},
144			{"第二段开始前1纳秒", time.Date(2026, 3, 20, 0, 0, 0, 0, time.UTC).Add(-time.Nanosecond)},
145			{"全部到期之后", time.Date(2026, 3, 30, 0, 0, 0, 0, time.UTC)},
146			{"更远的未来", time.Date(2026, 4, 1, 0, 0, 0, 0, time.UTC)},
147		}
148		for _, c := range none {
149			if _, err := b.EffectiveVersionAt("gap", c.at); !errors.Is(err, ErrNoEffectiveVersion) {
150				t.Fatalf("%s: want ErrNoEffectiveVersion, got %v", c.name, err)
151			}
152		}
153	
154		// 区间内命中各自版本，边界相接点由后一段取得。
155		got, err := b.EffectiveVersionAt("gap", time.Date(2026, 3, 5, 0, 0, 0, 0, time.UTC))
156		if err != nil || got.VersionID != "g1" {
157			t.Fatalf("空档场景 g1: %+v (%v)", got, err)
158		}
159		got, err = b.EffectiveVersionAt("gap", time.Date(2026, 3, 20, 0, 0, 0, 0, time.UTC))
160		if err != nil || got.VersionID != "g2" {
161			t.Fatalf("空档场景 g2 起点: %+v (%v)", got, err)
162		}
163	}
164	
165	// 从未登记过的费率项沿用现有的费率项不存在错误，
166	// 与“项存在但该时刻无生效版本”是两种可区分的失败。
167	func TestEffectiveVersionAtMissingItemVsNoVersion(t *testing.T) {
168		b, _ := newEffectiveVersionBook(t, effV1Start)
169	
170		_, err := b.EffectiveVersionAt("never-seen", effV1Start)
171		if !errors.Is(err, ErrItemNotFound) {
172			t.Fatalf("从未登记的费率项应返回 ErrItemNotFound, got %v", err)
173		}
174		if errors.Is(err, ErrNoEffectiveVersion) {
175			t.Fatalf("费率项不存在不能被误报成该时刻无生效版本: %v", err)
176		}
