	_, err = book.ItemVersionsInRange("seat", day(10), day(10))
	fmt.Printf("⑥ 结束等于开始：err=%v\n", err)
	fmt.Printf("   errors.Is(err, tariff.ErrInvalidRange) = %v\n\n",
		errors.Is(err, tariff.ErrInvalidRange))

	// ⑦ 范围合法但费率项从未登记过版本：沿用现有的费率项未找到错误。
